import requests
from urllib.parse import urljoin
from bs4 import BeautifulSoup
import csv
def task_func(url: str, base_url: str = "https://www.example.com", csv_file: str = "scraped_data.csv") -> int:
    if not url:
        raise ValueError("URL must be a non-empty string.")
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to connect to {url}: {e}")
    soup = BeautifulSoup(response.text, 'html.parser')
    links = set()
    for a_tag in soup.find_all('a', href=True):
        absolute_url = urljoin(base_url, a_tag['href'])
        links.add(absolute_url)
    with open(csv_file, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['Links'])
        for link in sorted(links):
            writer.writerow([link])
    return len(links)

import requests
import pandas as pd
import matplotlib.pyplot as plt
def task_func(api_url):
    if not isinstance(api_url, str):
        raise TypeError("api_url must be a string")
    try:
        response = requests.get(api_url, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise requests.HTTPError(f"API request failed: {e}") from e
    if not data:
        return pd.DataFrame(), None
    df = pd.DataFrame(data)
    numeric_cols = df.select_dtypes(include='number').columns
    if len(numeric_cols) > 0:
        ax = df[numeric_cols].plot()
    else:
        ax = None
    return df, ax

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0] if tree.xpath('//table') else None
        if table is None:
            return 0
        rows = table.xpath('.//tr')
        if not rows:
            return 0
        headers = []
        data_rows = []
        for i, row in enumerate(rows):
            cells = row.xpath('.//th | .//td')
            if i == 0 and any(cell.tag == 'th' for cell in cells):
                headers = [cell.text_content().strip() for cell in cells]
            else:
                data_rows.append([cell.text_content().strip() for cell in cells])
        if not data_rows:
            return 0
        df = pd.DataFrame(data_rows, columns=headers if headers else None)
        try:
            conn = sqlite3.connect(database_name)
            df.to_sql('my_table', conn, if_exists='replace', index=False)
            row_count = len(df)
            conn.close()
            return row_count
        except sqlite3.DatabaseError as e:
            raise sqlite3.DatabaseError(f"Database error: {e}")
    except Exception as e:
        if not isinstance(e, (requests.RequestException, sqlite3.DatabaseError)):
            raise ValueError(f"Error processing HTML: {e}")
        raise

